const reports = [
  ['hazard','Pothole near pedestrian crossing','Neftchilar Avenue',18,40.3655,49.8351,'Deep pothole in the right lane near the crossing.'],['infrastructure','Streetlight out','Rashid Behbudov Street',9,40.3802,49.8427,'Light has been out for the last two evenings.'],['event','Neighborhood market open','Fountains Square',23,40.3719,49.8368,'Small makers market with live music this afternoon.'],['crowd','Heavy crowd at metro entrance','28 May Station',31,40.3798,49.8508,'Crowd is moving slowly but steadily.'],['hazard','Loose construction barrier','Azadliq Avenue',7,40.3878,49.8387,'Barrier is partially in the pedestrian path.'],['infrastructure','Water leak on sidewalk','Khanlar Street',12,40.3842,49.8600,'Water has pooled beside the curb.'],['hazard','Unmarked pavement works','Uzeyir Hajibeyov Street',6,40.3740,49.8516,'No visible pedestrian detour at the work area.'],['crowd','Busy waterfront walkway','Baku Boulevard',14,40.3673,49.8474,'High foot traffic around the waterfront promenade.'],['event','Open-air performance starting','Seaside Park',16,40.3659,49.8429,'Community performance starting shortly by the park.'],['infrastructure','Damaged curb ramp','Samed Vurgun Street',8,40.3770,49.8321,'Curb ramp surface is cracked and uneven.'],['hazard','Signal timing concern','Nizami Street crossing',11,40.3732,49.8276,'Short crossing time reported by several residents.'],['infrastructure','Overflowing public bin','Sahil Metro',5,40.3681,49.8374,'Bin needs emptying near the station entrance.'],['event','Community clean-up point','Winter Park',19,40.3763,49.8329,'Volunteers meeting for a neighborhood clean-up.'],['crowd','Queue building at bus stop','Government House stop',10,40.3756,49.8478,'Longer-than-usual waiting queue at peak hour.'],['hazard','Slippery surface after cleaning','Torgovaya',4,40.3703,49.8309,'Wet paving reported near a pedestrian route.'],['infrastructure','Loose paving stones','Icherisheher edge',6,40.3664,49.8302,'Several loose stones near the pedestrian walkway.'],['event','Local art pop-up','Nizami Museum area',21,40.3695,49.8350,'Independent artists exhibiting outdoors today.'],['crowd','Congestion near taxi rank','Port Baku',17,40.3847,49.8552,'Vehicles and pedestrians are moving slowly.'],['hazard','Cycling lane obstruction','Boulevard east section',8,40.3714,49.8580,'Temporary obstruction in the cycling lane.'],['infrastructure','Bench needs repair','Molokan Garden',3,40.3737,49.8420,'Damaged seat slat reported by park visitors.'],['event','Public chess tables active','Khagani Garden',15,40.3737,49.8385,'Community games underway in the garden.'],['crowd','High activity near food stalls','Fountains Square',13,40.3728,49.8378,'Crowd conditions remain comfortable but active.'],['hazard','Poor visibility at corner','Bashir Safaroglu Street',5,40.3787,49.8289,'Parked vehicles are blocking the sight line.'],['infrastructure','Drinking fountain unavailable','Boulevard promenade',6,40.3651,49.8504,'Public drinking fountain is not running.']
].map(([category,title,location,confirmations,lat,lng,description],index)=>({id:index+1,category,title,location,confirmations,lat,lng,description,time:index<4?`${12+index*16} min ago`:`${Math.ceil(index/3)} hrs ago`}));
const feed=document.querySelector('#feedList'),count=document.querySelector('#allCount');let activeFilter='all';
const map=L.map('map',{zoomControl:false,attributionControl:false,minZoom:13,maxZoom:18}).setView([40.374,49.842],14);L.control.zoom({position:'bottomright'}).addTo(map);L.control.attribution({position:'bottomleft',prefix:false}).addAttribution('&copy; OpenStreetMap contributors');L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const markers=L.layerGroup().addTo(map);
requestAnimationFrame(()=>map.invalidateSize());window.addEventListener('resize',()=>map.invalidateSize());
const label=r=>`${r.title} · ${r.confirmations} confirmed`,color=c=>({hazard:'#ff704b',infrastructure:'#9786f4',event:'#5bd4c1',crowd:'#f6b451',emergency:'#d84f4f'})[c],iconFor=c=>({hazard:'!',infrastructure:'⌁',event:'✦',crowd:'●',emergency:'+'})[c];
const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[char]);
function addMarker(r){const icon=L.divIcon({className:'pulse-marker-wrap',html:`<button class="pulse-marker ${r.category}" aria-label="${escapeHtml(label(r))}"><span>${iconFor(r.category)}</span></button>`,iconSize:[34,34],iconAnchor:[17,17]});const marker=L.marker([r.lat,r.lng],{icon,keyboard:true}).addTo(markers);marker.on('click',()=>selectReport(r));}
function selectReport(r){document.querySelector('#panelCategory').textContent=`${r.category.toUpperCase()} · ${r.confirmations>15?'HIGH ATTENTION':'COMMUNITY SIGNAL'}`;document.querySelector('#panelTitle').textContent=r.title;document.querySelector('#panelLocation').textContent=`${r.location} · ${r.time}`;document.querySelector('#panelDescription').textContent=r.description;document.querySelector('#panelConfirmations').textContent=r.confirmations;document.querySelector('#mapPanel').classList.add('open');map.flyTo([r.lat,r.lng],16,{duration:.55});document.querySelector('#confirmReport').onclick=()=>{r.confirmations++;render();selectReport(r);showToast('Thanks — your confirmation improves this report’s credibility.');};}
function render(){const query=document.querySelector('#searchInput').value.toLowerCase();const shown=reports.filter(r=>(activeFilter==='all'||r.category===activeFilter)&&(`${r.title} ${r.location} ${r.description}`).toLowerCase().includes(query));markers.clearLayers();shown.forEach(addMarker);feed.innerHTML=shown.map(r=>`<article class="feed-card"><i class="feed-type" style="background:${color(r.category)}"></i><div><span class="feed-tag">${r.category}</span><h3>${escapeHtml(r.title)}</h3><p>${escapeHtml(r.location)} · ${escapeHtml(r.description)}</p></div><time>${r.time}</time></article>`).join('')||'<p>No reports match your search yet.</p>';count.textContent=reports.length;document.querySelector('#activeReports').textContent=reports.length;}
function showToast(message){const toast=document.createElement('div');toast.textContent=message;Object.assign(toast.style,{position:'fixed',bottom:'24px',left:'50%',transform:'translateX(-50%)',background:'#11212a',color:'#fff',padding:'11px 16px',borderRadius:'6px',fontSize:'12px',zIndex:1000,boxShadow:'0 4px 14px #0004'});document.body.append(toast);setTimeout(()=>toast.remove(),2800);}
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('selected',x===b));render();}));document.querySelector('#searchInput').addEventListener('input',render);document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));document.querySelector(`#${b.dataset.view}View`).classList.add('active');}));
const drawer=document.querySelector('#reportDrawer'),openDrawer=()=>{drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');document.querySelector('#reportLocation').focus();},closeDrawer=()=>{drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');};document.querySelector('#openReport').addEventListener('click',openDrawer);document.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',closeDrawer));
document.querySelector('#reportForm').addEventListener('submit',e=>{e.preventDefault();const category=document.querySelector('#reportCategory').value,location=document.querySelector('#reportLocation').value,description=document.querySelector('#reportDescription').value;reports.unshift({id:Date.now(),category,title:description.slice(0,54)+(description.length>54?'…':''),location,time:'just now',confirmations:1,lat:40.368+Math.random()*.018,lng:49.827+Math.random()*.03,description});render();closeDrawer();e.target.reset();showToast('Report shared. Thanks for helping your city stay informed.');});
const modal=document.querySelector('#municipalModal');document.querySelector('#openMunicipal').addEventListener('click',()=>{modal.classList.add('open');modal.setAttribute('aria-hidden','false');});document.querySelectorAll('[data-close-modal]').forEach(x=>x.addEventListener('click',()=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true');}));document.querySelector('#aboutButton').addEventListener('click',()=>modal.classList.add('open'));document.querySelector('#closePanel').addEventListener('click',()=>document.querySelector('#mapPanel').classList.remove('open'));document.querySelector('#viewFeed').addEventListener('click',()=>document.querySelector('[data-view="feed"]').click());render();
function renderFallback(){const target=document.querySelector('#fallbackMarkers');if(!target)return;const query=document.querySelector('#searchInput').value.toLowerCase();const shown=reports.filter(r=>(activeFilter==='all'||r.category===activeFilter)&&(`${r.title} ${r.location} ${r.description}`).toLowerCase().includes(query));const minLat=40.362,maxLat=40.391,minLng=49.824,maxLng=49.865;target.innerHTML='';shown.forEach(r=>{const el=document.createElement('button');el.className=`fallback-marker ${r.category}`;el.style.left=`${((r.lng-minLng)/(maxLng-minLng))*100}%`;el.style.top=`${100-((r.lat-minLat)/(maxLat-minLat))*100}%`;el.innerHTML=`<span>${iconFor(r.category)}</span><b>${r.confirmations}</b>`;el.title=label(r);el.addEventListener('click',()=>selectReport(r));target.append(el);});}
renderFallback();document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',renderFallback));document.querySelector('#searchInput').addEventListener('input',renderFallback);
let pendingLocation=null,pinMode=false;const locationStatus=document.querySelector('#locationStatus');
function setPendingLocation(lat,lng,label){pendingLocation={lat,lng,label};locationStatus.textContent=label;document.querySelector('#reportLocation').value=label;pinMode=false;showToast('Location pinned — finish your report when ready.');}
document.querySelector('#useMyLocation').addEventListener('click',()=>{if(!navigator.geolocation){showToast('Location is not available in this browser. Drop a pin on the map instead.');return;}locationStatus.textContent='Finding your location…';navigator.geolocation.getCurrentPosition(p=>{setPendingLocation(p.coords.latitude,p.coords.longitude,'Current location');map.flyTo([p.coords.latitude,p.coords.longitude],16);},()=>{locationStatus.textContent='Location unavailable — drop a pin instead';showToast('We could not access your location. You can place a pin manually.');},{enableHighAccuracy:true,timeout:10000});});
document.querySelector('#pickOnMap').addEventListener('click',()=>{pinMode=true;closeDrawer();document.querySelector('#mapFallback').classList.add('pin-mode');showToast('Tap a point on the map to place your report.');});
document.querySelector('#mapFallback').addEventListener('click',e=>{if(!pinMode)return;const box=e.currentTarget.getBoundingClientRect(),x=(e.clientX-box.left)/box.width,y=(e.clientY-box.top)/box.height,minLat=40.362,maxLat=40.391,minLng=49.824,maxLng=49.865;setPendingLocation(maxLat-y*(maxLat-minLat),minLng+x*(maxLng-minLng),'Pinned map location');e.currentTarget.classList.remove('pin-mode');openDrawer();});
document.querySelector('#reportForm').addEventListener('submit',()=>{if(!pendingLocation)return;setTimeout(()=>{if(reports[0]){reports[0].lat=pendingLocation.lat;reports[0].lng=pendingLocation.lng;reports[0].location=pendingLocation.label;render();renderFallback();pendingLocation=null;locationStatus.textContent='No map location selected';}},0);});
const profileModal=document.querySelector('#profileModal'),profileButton=document.querySelector('#openProfile');function openProfile(){profileModal.classList.add('open');profileModal.setAttribute('aria-hidden','false');document.querySelector('#firstName').value=localStorage.getItem('pulseFirstName')||'';document.querySelector('#lastName').value=localStorage.getItem('pulseLastName')||'';}profileButton.addEventListener('click',openProfile);document.querySelectorAll('[data-close-profile]').forEach(x=>x.addEventListener('click',()=>{profileModal.classList.remove('open');profileModal.setAttribute('aria-hidden','true');}));document.querySelector('#profileForm').addEventListener('submit',e=>{e.preventDefault();const first=document.querySelector('#firstName').value.trim(),last=document.querySelector('#lastName').value.trim();localStorage.setItem('pulseFirstName',first);localStorage.setItem('pulseLastName',last);profileButton.textContent=((first[0]||'F')+(last[0]||'S')).toUpperCase();profileModal.classList.remove('open');showToast('Profile saved on this device.');});document.querySelectorAll('.route-button').forEach(b=>b.addEventListener('click',()=>showToast('This is a suggested routing guide; PULSE does not contact departments in this MVP.')));
